                                                                                                                                                                                                                    
  CREATE TABLE "FMP_OPERATION_LOG"                                                                                                                                                                        
   (	"OPERATION_LOG_ID" NUMBER(20,0) GENERATED BY DEFAULT AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 1 CACHE 20 NOORDER  NOCYCLE  NOKEEP  NOSCALE  NOT NULL ENABLE,     
	"OPERATION_ACTION" VARCHAR2(50),                                                                                                                                                                                   
	"OPERATION_MODULE" VARCHAR2(100),                                                                                                                                                                                  
	"OPERATION_CONTENT" VARCHAR2(255),                                                                                                                                                                                 
	"OPERATION_REFERENCE_ID" NUMBER(20,0),                                                                                                                                                                             
	"DEL_FLAG" NUMBER(1,0) DEFAULT 0,                                                                                                                                                                                  
	"TENANT_ID" NUMBER(10,0) DEFAULT 3,                                                                                                                                                                                
	"CREATED_BY" NUMBER(20,0),                                                                                                                                                                                         
	"CREATION_DATE" DATE DEFAULT sysdate,                                                                                                                                                                              
	"UPDATED_BY" NUMBER(20,0),                                                                                                                                                                                         
	"UPDATE_DATE" DATE DEFAULT sysdate,                                                                                                                                                                                
	"OPERATION_PARAMS" VARCHAR2(2000),                                                                                                                                                                                 
	 PRIMARY KEY ("OPERATION_LOG_ID")                                                                                                                                                                                  
  USING INDEX  ENABLE                                                                                                                                                                                               
   ) ;                                                                                                                                                                                                              


